import {STORAGE_KEY,FEATURES,STAGES,initialState,preferences,validateInventory,assess,deck,decide,undo,hydrate,stayEstimate,mapUrl} from './shortlist.js';
import {loadRentals,LIVE_STORAGE_KEY} from './rental-feed.js';
const demo=new URLSearchParams(location.search).get('demo')==='1';
const storageKey=demo?STORAGE_KEY:LIVE_STORAGE_KEY;
const freshState=()=>{const s=initialState();if(!demo)s.preferences.city='';return s;};
const $=id=>document.getElementById(id), money=n=>n===null?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,action)=>{const b=el('button',text);b.type='button';b.addEventListener('click',action);return b;};
let records=[],state=freshState(),view='discover',compare=false,timer;
function announce(text){clearTimeout(timer);$('announcement').textContent=text;$('announcement').hidden=false;timer=setTimeout(()=>$('announcement').hidden=true,5000);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));$('storage-status').textContent='Saved only in this browser. No account or cloud sync.';}catch{$('storage-status').textContent='Browser storage unavailable or full. Changes will be lost when you leave this page.';}}
function fillForm(){const f=$('preferences-form');for(const [key,value] of Object.entries(state.preferences)){if(key==='features')continue;const n=f.elements.namedItem(key);if(n){if(n.type==='checkbox')n.checked=value;else n.value=value;}}for(const key of Object.keys(FEATURES))f.elements.namedItem('feature-'+key).value=state.preferences.features[key]??'any';}
function switchView(next,focus=false){view=next;$('discover-view').hidden=next!=='discover';$('saved-view').hidden=next!=='saved';$('browse-tab').setAttribute('aria-pressed',String(next==='discover'));$('saved-tab').setAttribute('aria-pressed',String(next==='saved'));render();if(focus){const heading=$(next==='saved'?'saved-heading':'deck-title');heading.tabIndex=-1;heading.focus();}}
function makeDecision(id,choice){state=decide(state,id,choice,records);persist();const complete=view==='discover'&&deck(records,state).length===0;render();if(complete)switchView('saved',true);announce(complete?'Deck complete. Your saved places are ready to compare.':choice==='save'?'Saved to your shortlist. No one has been contacted.':'Passed. You can undo this decision.');}
function showMap(row){$('map-title').textContent=row.area+' · approximate neighborhood';const frame=el('iframe');frame.title='OpenStreetMap near '+row.area;frame.referrerPolicy='no-referrer';frame.src=mapUrl(row);const fallback=el('p',undefined,'help'),link=el('a','Open this neighborhood on OpenStreetMap ↗');link.href='https://www.openstreetmap.org/?mlat='+row.latitude+'&mlon='+row.longitude+'#map=14/'+row.latitude+'/'+row.longitude;link.target='_blank';link.rel='noopener noreferrer';fallback.append('If the embedded map is unavailable, ',link);$('map-container').replaceChildren(fallback,frame);$('map-panel').hidden=false;$('map-panel').scrollIntoView({behavior:'auto',block:'start'});$('close-map').focus();}
function content(row,saved=false){
  const wrapper=el('div'),photo=el('div',undefined,row.demo?'home-photo':'source-banner');if(row.demo){photo.style.backgroundPosition=(row.image_panel*50)+'% center';photo.append(el('span','FICTIONAL HOME · ILLUSTRATIVE PHOTO','photo-label'));}else{photo.append(el('p','LISTED BY '+row.source.toUpperCase(),'eyebrow'),el('strong',row.availability_label),el('p','Property photos and applications are on the original listing.','help'));}wrapper.append(photo);
  const body=el('div',undefined,'card-body');body.append(el('p',row.area+' · '+row.city+', '+row.state,'location'));const top=el('div',undefined,'listing-top');const title=el('h3',row.title),price=el('div',money(row.monthly_total??row.known_monthly_minimum)+(row.monthly_total===null?'+':''),'price');price.append(el('small',row.monthly_total===null?'known minimum / month':(row.demo?'estimated total / month':'base rent + utilities / month')));top.append(title,price);body.append(top);
  body.append(el('p',row.description));body.append(el('p','Rent '+money(row.rent)+' + utilities '+money(row.utilities)+' + recurring fees '+money(row.fees)+'. Deposit: '+money(row.deposit)+'.','costs'));
  if(!row.demo)body.append(el('p',row.fee_note,'help'),el('p',row.lease_months?'Published rates are for '+row.lease_months+'+ month leases. Ask the source for shorter-stay pricing.':'Lease length and shorter-stay pricing must be confirmed with the source.','help'));
  const fit=assess(row,state.preferences),pills=el('div',undefined,'pills');pills.append(el('span',row.bedrooms===0?'Room / studio':row.bedrooms+' bedroom'+(row.bedrooms>1?'s':''),'pill'));
  for(const text of fit.matched)pills.append(el('span',text,'pill good'));
  for(const text of fit.missing)pills.append(el('span',text+' unknown','pill unknown'));
  if(saved)for(const text of fit.reasons)pills.append(el('span',text,'pill mismatch'));
  body.append(pills);const details=el('details');details.append(el('summary',row.demo?'All sample details':'Details & source'));const list=el('ul');for(const [key,label] of Object.entries(FEATURES))list.append(el('li',label+': '+(row.features[key]===null?'Unknown':row.features[key]?'Yes':'No')));details.append(list,el('p',row.demo?'Illustrative date window: '+row.available_from+' to '+row.available_to+'. Sample data date: '+row.updated+'; not verified availability.':'Source: '+row.source+'. Feed generated '+new Date(row.updated).toLocaleString()+'. '+(row.availability_checked?'Calendar refreshed '+new Date(row.availability_checked).toLocaleString()+'. ':'')+'Full-stay availability must be confirmed on the original site.','help'));body.append(details);
  const estimate=stayEstimate(row,state.preferences);if(estimate)body.append(el('p','Planning estimate: '+money(estimate.amount)+' for '+estimate.days+' nights using 30-day proration. Excludes deposit and one-off charges; not a quote.','help'));
  const controls=el('div',undefined,'card-controls');controls.append(button('View neighborhood map',()=>showMap(row)));if(row.demo){const unavailable=button('Sample — no application',()=>{});unavailable.disabled=true;controls.append(unavailable);}else{const original=el('a','View original listing ↗','primary source-link');original.href=row.source_url;original.target='_blank';original.rel='noopener noreferrer';original.setAttribute('aria-label','View original listing for '+row.title+' on '+row.source);controls.append(original);}body.append(controls);
  if(saved){const editor=el('div',undefined,'private-notes'),entry=state.details[row.id]??{stage:'Saved',notes:''},stageLabel=el('label','Your progress (private)'),select=el('select');select.setAttribute('aria-label','Progress for '+row.title);for(const text of STAGES){const option=el('option',text);option.value=text;select.append(option);}select.value=entry.stage;stageLabel.append(select);select.addEventListener('change',()=>{state.details[row.id]={...entry,...state.details[row.id],stage:select.value};persist();renderSaved();});const notesLabel=el('label','Your notes'),notes=el('textarea');notes.maxLength=1000;notes.value=entry.notes;notes.placeholder='Questions, viewing notes, next steps…';notes.setAttribute('aria-label','Notes for '+row.title);notes.addEventListener('input',()=>{state.details[row.id]={...entry,...state.details[row.id],notes:notes.value};persist();});notesLabel.append(notes);editor.append(stageLabel,notesLabel,button('Remove from saved',()=>makeDecision(row.id,'pass')));body.append(editor);}
  wrapper.append(body);return wrapper;
}
function renderSaved(){const saved=records.filter(r=>state.decisions[r.id]==='save'),filter=$('stage-filter').value,visible=saved.filter(r=>filter==='all'||(state.details[r.id]?.stage??'Saved')===filter);$('saved-empty').hidden=saved.length>0;$('stage-empty').hidden=saved.length===0||visible.length>0;$('saved-list').replaceChildren(...visible.map(row=>{const card=el('article',undefined,'saved-card');card.append(content(row,true));return card;}));$('compare-toggle').disabled=visible.length===0;$('comparison').hidden=!compare||visible.length===0;$('compare-toggle').setAttribute('aria-expanded',String(compare&&visible.length>0));
  const table=el('table');table.append(el('caption',demo?'Sample costs only. Unknown utilities are never treated as zero.':'Source-reported base monthly costs. Extra charges may apply; confirm on the original listing.'));const head=el('thead'),tr=el('tr');for(const t of ['Place','Rent / month','Utilities / month','Fees / month',demo?'Total / month':'Base + utilities / month','Deposit']){const th=el('th',t);th.scope='col';tr.append(th);}head.append(tr);table.append(head);const body=el('tbody');for(const r of visible){const tr=el('tr');const name=el('th',r.title);name.scope='row';tr.append(name);for(const value of [r.rent,r.utilities,r.fees,r.monthly_total,r.deposit])tr.append(el('td',money(value)));body.append(tr);}table.append(body);$('comparison').replaceChildren(table);
}
function render(){const choices=deck(records,state),eligible=records.filter(r=>assess(r,state.preferences).eligible);$('saved-count').textContent=records.filter(r=>state.decisions[r.id]==='save').length;$('deck-count').textContent=choices.length+' remaining';$('filter-summary').textContent='Matches your known must-haves, then ranks preferences and monthly cost. '+eligible.length+' of '+records.length+(demo?' sample homes fit.':' source listings fit.')+' Unknown costs may exceed your budget.';$('listing-card').hidden=!choices.length;$('deck-actions').hidden=!choices.length;$('swipe-help').hidden=!choices.length;$('deck-empty').hidden=!!choices.length;$('undo').disabled=state.history.length===0;if(choices.length)$('listing-card').replaceChildren(content(choices[0].row));else{$('listing-card').replaceChildren();$('empty-title').textContent=eligible.length?'You’ve reached the end.':demo?'No sample homes match.':'No listings match these filters.';$('empty-copy').textContent=eligible.length?'Your favorites are waiting in Saved. Review passed places or change your preferences to explore again.':demo?'Try a higher budget or fewer must-haves. This demo has only Los Angeles samples—not nationwide inventory.':'Our first source covers Pensacola, Florida. Try clearing the city or adjusting filters. We do not yet have nationwide or all-platform inventory.';}$('review-passed').disabled=!Object.values(state.decisions).includes('pass');renderSaved();}
for(const [key,label] of Object.entries(FEATURES)){const field=el('label',label),select=el('select');select.name='feature-'+key;for(const [value,text] of [['any','No preference'],['want','Prefer'],['need','Must have'],['avoid','Must not have']]){const option=el('option',text);option.value=value;select.append(option);}field.append(select);$('feature-fields').append(field);}
for(const text of STAGES){const option=el('option',text);option.value=text;$('stage-filter').append(option);}
$('preferences-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),input=Object.fromEntries(data),features={};for(const key of Object.keys(FEATURES))features[key]=data.get('feature-'+key);try{state.preferences=preferences({...input,features,hideUnknown:data.has('hideUnknown')});$('filter-error').hidden=true;persist();render();announce('Preferences updated. Your saved places are unchanged.');}catch(error){$('filter-error').textContent=error.message;$('filter-error').hidden=false;}});
$('reset-preferences').onclick=()=>{state.preferences=freshState().preferences;fillForm();$('filter-error').hidden=true;persist();render();};
$('browse-tab').onclick=$('continue-browsing').onclick=()=>switchView('discover',true);$('saved-tab').onclick=$('show-saved').onclick=()=>switchView('saved',true);
$('pass').onclick=()=>{const row=deck(records,state)[0]?.row;if(row)makeDecision(row.id,'pass');};$('save').onclick=()=>{const row=deck(records,state)[0]?.row;if(row)makeDecision(row.id,'save');};
$('undo').onclick=()=>{state=undo(state);persist();render();announce('Last decision undone.');};
$('review-passed').onclick=()=>{for(const [id,value] of Object.entries(state.decisions))if(value==='pass')delete state.decisions[id];state.history=[];persist();render();announce('Passed places are back in your deck.');};
$('stage-filter').onchange=renderSaved;$('compare-toggle').onclick=()=>{compare=!compare;renderSaved();};$('close-map').onclick=()=>{$('map-panel').hidden=true;$('map-container').replaceChildren();$(view==='saved'?'saved-tab':'browse-tab').focus();};
$('clear-shortlist').onclick=()=>$('clear-dialog').showModal();$('cancel-clear').onclick=()=>$('clear-dialog').close();$('confirm-clear').onclick=()=>{state=freshState();try{localStorage.removeItem(storageKey);}catch{}fillForm();$('stage-filter').value='all';compare=false;$('clear-dialog').close();$('map-panel').hidden=true;$('map-container').replaceChildren();persist();switchView('discover');announce('Shortlist reset. Previous demo profiles are untouched.');};
$('listing-card').addEventListener('keydown',event=>{if(event.target!==$('listing-card'))return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();$(event.key==='ArrowLeft'?'pass':'save').click();}});
let gesture=null;$('listing-card').addEventListener('pointerdown',event=>{if(event.target.closest('button,a,summary,select,input,textarea'))return;gesture={x:event.clientX,y:event.clientY,id:event.pointerId};});
$('listing-card').addEventListener('pointercancel',()=>gesture=null);$('listing-card').addEventListener('pointerup',event=>{if(!gesture||gesture.id!==event.pointerId)return;const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;gesture=null;if(Math.abs(dx)>80&&Math.abs(dx)>1.5*Math.abs(dy))$(dx>0?'save':'pass').click();});
if(demo){$('inventory-notice').textContent='Demo mode: eight fictional Los Angeles homes. No real applications. Demo saves are separate from real listings.';$('city-help').textContent='Sample inventory is LA only.';$('mode-link').textContent='Browse real listings →';$('mode-link').href='/';$('listing-card').setAttribute('aria-label','Sample home. Left arrow passes; right arrow saves.');}
try{if(demo){const response=await fetch('/data/listings.json');if(!response.ok)throw Error('Unable to load');records=validateInventory(await response.json());}else{records=await loadRentals();$('inventory-notice').textContent=records.length+' real property listings from Mi Casa Rentals in Pensacola, Florida. Not nationwide or all-platform coverage. Availability and prices can change; inquire or apply on the original site. No NestMatch booking fee.';}try{const raw=localStorage.getItem(storageKey);if(raw)state=hydrate(JSON.parse(raw),records);}catch{$('storage-status').textContent='Could not read saved data. Starting a temporary new session.';}fillForm();render();$('load-status').hidden=true;$('app').hidden=false;}catch{$('load-status').textContent=demo?'The sample inventory could not be loaded. Please reload, or use the rental guides. No listing actions are available.':'The rental source is unavailable or out of date. Reload to try again, or visit Mi Casa Rentals directly using the source link above. We have not substituted demo listings.';$('browse-tab').disabled=true;$('saved-tab').disabled=true;}
